BEGIN;

-- Codes are generated by PostgreSQL so concurrent inserts cannot collide and
-- clients can never choose an internal identifier.
CREATE SEQUENCE "property_code_seq" AS BIGINT START WITH 1 INCREMENT BY 1;

ALTER TABLE "properties"
ALTER COLUMN "code"
SET DEFAULT (
  'HK-' ||
  to_char(CURRENT_DATE, 'YYYY') ||
  '-' ||
  lpad(nextval('property_code_seq')::text, 6, '0')
);

COMMIT;
